const state = { stage: 'reference', panel: 'issue', selectedIssue: 'joint', confirmed: false, history: [] };
const $ = (id) => document.getElementById(id);
const toast = (message) => { const el = $('toast'); el.textContent = message; el.classList.remove('hidden'); el.classList.add('show'); setTimeout(() => el.classList.add('hidden'), 2200); };
const pushPanel = (panel) => { state.panel = panel; history.pushState({ panel }, '', `#${panel}`); renderPanel(); };
const renderPanel = () => { $('issue-panel').classList.toggle('hidden', state.panel !== 'issue'); $('reference-panel').classList.toggle('hidden', state.panel !== 'reference'); $('design-panel').classList.toggle('hidden', state.panel !== 'design'); $('package-panel').classList.toggle('hidden', state.panel !== 'package'); const titles = { issue:['需要你的确认','接合方式'], reference:['项目上下文','参考资料'], design:['当前设计','尺寸与材料'], package:['加工包','设计确认后生成'] }; $('panel-kicker').textContent = titles[state.panel][0]; $('panel-title').textContent = titles[state.panel][1]; $('package-button').classList.toggle('locked', !state.confirmed); $('package-status-title').textContent = state.confirmed ? '加工包已解锁' : '确认设计后解锁'; };
const renderStage = () => { $('reference-state').classList.toggle('hidden', state.stage !== 'reference'); $('model-state').classList.toggle('hidden', state.stage !== 'model'); $('airport-state').classList.toggle('hidden', state.stage !== 'airport'); $('stage-eyebrow').textContent = state.stage === 'reference' ? '参考已导入 · 结构候选未确认' : state.stage === 'model' ? (state.confirmed ? '设计已确认 · 可生成加工包' : '结构候选 · v3 draft') : 'Airport 预览 · v3'; $('stage-title').textContent = state.stage === 'reference' ? '先把喜欢的椅子看懂' : state.stage === 'model' ? '围绕模型继续设计' : '模型已进入 Airport'; $('commit-button').classList.toggle('locked', !state.confirmed || state.stage === 'airport'); $('commit-button').textContent = state.stage === 'airport' ? '已提交' : '提交 Airport'; $('save-state').textContent = state.confirmed ? '已保存 · v4' : '已保存 · v3'; };
const renderIssues = () => { document.querySelectorAll('.issue').forEach((el) => el.classList.toggle('selected', el.dataset.issue === state.selectedIssue)); };
const render = () => { renderStage(); renderPanel(); renderIssues(); };
document.querySelectorAll('[data-panel]').forEach((el) => el.addEventListener('click', () => pushPanel(el.dataset.panel)));
document.querySelectorAll('.issue').forEach((el) => el.addEventListener('click', () => { state.selectedIssue = el.dataset.issue; pushPanel('issue'); toast(el.querySelector('strong').textContent); }));
document.querySelectorAll('[data-action="generate"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; pushPanel('issue'); toast('已生成结构候选，等待确认'); }));
document.querySelectorAll('[data-action="confirm"]').forEach((el) => el.addEventListener('click', () => { state.confirmed = true; render(); toast('设计已确认，加工包已解锁'); }));
document.querySelectorAll('[data-action="apply-joint"]').forEach((el) => el.addEventListener('click', () => { document.querySelector('[data-issue="joint"] strong').textContent = '接合方式已确认'; document.querySelector('[data-issue="joint"] small').textContent = '半搭接 · 已应用'; document.querySelector('[data-issue="joint"]').classList.remove('blocker'); document.querySelector('[data-issue="joint"]').classList.add('notice'); toast('已应用半搭接，承载估算仍待确认'); }));
document.querySelectorAll('[data-action="select-joint"]').forEach((el) => el.addEventListener('click', () => { document.querySelectorAll('.option').forEach((option) => option.classList.remove('selected-option')); el.classList.add('selected-option'); }));
document.querySelectorAll('[data-action="commit"]').forEach((el) => el.addEventListener('click', () => { if (!state.confirmed) { pushPanel('issue'); toast('请先确认设计'); return; } state.stage = 'airport'; render(); toast('已提交 Airport 预览'); }));
document.querySelectorAll('[data-action="back-model"]').forEach((el) => el.addEventListener('click', () => { state.stage = 'model'; render(); }));
document.querySelectorAll('[data-action="close-panel"]').forEach((el) => el.addEventListener('click', () => { document.querySelector('.right-panel').classList.toggle('closed'); }));
document.querySelectorAll('[data-action="export"]').forEach((el) => el.addEventListener('click', () => { pushPanel('package'); toast(state.confirmed ? '加工包已准备好下载' : '确认设计后才能导出加工包'); }));
document.querySelector('[data-action="package"]').addEventListener('click', () => { if (!state.confirmed) { toast('请先确认设计'); return; } toast('加工包已生成，可以下载'); });
document.querySelectorAll('[data-command]').forEach((el) => el.addEventListener('click', () => { $('command-input').value = el.dataset.command; $('command-input').focus(); }));
$('command-input').addEventListener('keydown', (event) => { if (event.key === 'Enter') document.querySelector('[data-action="command"]').click(); });
document.querySelector('[data-action="command"]').addEventListener('click', () => { const value = $('command-input').value.trim(); if (!value) return; state.history.push(value); $('command-input').value = ''; toast(`AI 已收到：“${value}”`); pushPanel('issue'); });
document.querySelector('[data-panel="material"]')?.addEventListener('click', () => pushPanel('design'));
window.addEventListener('popstate', (event) => { state.panel = event.state?.panel || 'issue'; renderPanel(); });
render();
